scripts.home:
function handle(req) {
  return {template: 'home', data: {products: db.query('SELECT id, name, price_aed FROM products ORDER BY name')}};
}

scripts.product:
function handle(req) {
  const rows = db.query('SELECT * FROM products WHERE id = ?', Number(req.params.id));
  if (rows.length === 0) return {template: 'not_found', status: 404};
  return {template: 'product', data: {product: rows[0]}};
}

scripts.order:
function handle(req) {
  const f = req.form;
  if (!f.customer_name || !f.phone) return {text: 'name and phone are required', status: 400};
  const p = db.query('SELECT id FROM products WHERE id = ?', Number(f.product_id));
  if (p.length === 0) return {text: 'unknown product', status: 400};
  const r = db.exec('INSERT INTO orders (product_id, customer_name, phone) VALUES (?, ?, ?)', p[0].id, f.customer_name, f.phone);
  console.log('new order', r.lastInsertId);
  return {template: 'thanks', data: {id: r.lastInsertId, name: f.customer_name}};
}

